    "送り出し": "Envois",
    "終了日時（任意）": "Date de fin (facultatif)",
    "過去のシーズン": "Saisons passées",
    "　{0}〜{1}・参加 {2}人": "{0} à {1} · {2} participants",
    "{0}（{1}）戦果 {2}%": "{0} ({1}) résultats {2} %",
